import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import json
from datetime import datetime
import warnings
warnings.filterwarnings('ignore')

# Style configuration
plt.style.use('seaborn-v0_8-darkgrid')
sns.set_palette("muted")

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=300, bbox_inches='tight')
    buf.seek(0)
    img_str = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return img_str

# Read data
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], format='%d-%m-%y')
df = df.sort_values('Date').reset_index(drop=True)

# Clean and calculate basic metrics
df['Log_Return'] = np.log(df['Close'] / df['Close'].shift(1))
df['Return'] = df['Close'].pct_change()
df['Rolling_Vol_30'] = df['Log_Return'].rolling(window=30).std() * np.sqrt(252)
df['Rolling_Vol_90'] = df['Log_Return'].rolling(window=90).std() * np.sqrt(252)

# KPIs
years = (df['Date'].max() - df['Date'].min()).days / 365.25
cagr = (df['Close'].iloc[-1] / df['Close'].iloc[0]) ** (1 / years) - 1
ann_vol = df['Log_Return'].std() * np.sqrt(252)

cumulative_max = df['Close'].cummax()
drawdown = (df['Close'] - cumulative_max) / cumulative_max
max_drawdown = drawdown.min()

avg_volume = df['Volume'].mean()
sharpe_ratio = cagr / ann_vol if ann_vol != 0 else 0

# --- Visualizations ---

# 1. Price Trend & Drawdown
fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(12, 8), height_ratios=[3, 1], sharex=True)
ax1.plot(df['Date'], df['Close'], color='#2c3e50', linewidth=1.5)
ax1.set_title('Gold Price Evolution (2000-2025)', fontsize=14, fontweight='bold')
ax1.set_ylabel('Price (USD)')
ax1.fill_between(df['Date'], df['Close'], alpha=0.1, color='#2c3e50')

ax2.fill_between(df['Date'], drawdown * 100, 0, color='#e74c3c', alpha=0.5)
ax2.plot(df['Date'], drawdown * 100, color='#c0392b', linewidth=1)
ax2.set_title('Drawdown (%)', fontsize=12)
ax2.set_ylabel('% Drawdown')
plt.tight_layout()
trend_img = fig_to_base64(fig)

# 2. Volatility Analysis & Regimes
fig, ax = plt.subplots(figsize=(12, 5))
ax.plot(df['Date'], df['Rolling_Vol_90'] * 100, color='#8e44ad', linewidth=1.5)
ax.axhline(y=(ann_vol*100), color='k', linestyle='--', label=f'Avg Vol ({ann_vol*100:.1f}%)')

# High volatility regions (> 75th percentile of 90-day vol)
vol_75 = df['Rolling_Vol_90'].quantile(0.75) * 100
ax.axhline(y=vol_75, color='r', linestyle=':', label='High Vol Threshold')
ax.fill_between(df['Date'], df['Rolling_Vol_90'] * 100, vol_75, 
                where=(df['Rolling_Vol_90'] * 100 > vol_75), color='r', alpha=0.3)

ax.set_title('Rolling 90-Day Annualized Volatility', fontsize=14, fontweight='bold')
ax.set_ylabel('Volatility (%)')
ax.legend()
plt.tight_layout()
vol_img = fig_to_base64(fig)

# 3. Seasonal Patterns (Monthly)
df['Month'] = df['Date'].dt.month
monthly_returns = df.groupby(['Month', df['Date'].dt.year])['Return'].sum().reset_index()
fig, ax = plt.subplots(figsize=(10, 5))
sns.boxplot(x='Month', y='Return', data=monthly_returns, ax=ax, palette='Blues_d')
ax.set_xticklabels(['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'])
ax.set_title('Monthly Return Distribution', fontsize=14, fontweight='bold')
ax.set_ylabel('Monthly Return')
# T-tests for seasonality
monthly_mean = monthly_returns.groupby('Month')['Return'].mean()
ax.plot(range(12), monthly_mean, color='red', marker='o', linestyle='-', linewidth=2, label='Mean Return')
ax.legend()
plt.tight_layout()
season_img = fig_to_base64(fig)

# 4. Return Distribution
fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 5))
sns.histplot(df['Return'].dropna() * 100, bins=100, kde=True, ax=ax1, color='#3498db')
ax1.set_title('Daily Returns Distribution (%)', fontsize=12)
ax1.set_xlabel('Daily Return (%)')
ax1.set_xlim(-5, 5)

import scipy.stats as stats
stats.probplot(df['Return'].dropna(), dist="norm", plot=ax2)
ax2.set_title('Q-Q Plot (Tail Risk)', fontsize=12)
plt.tight_layout()
dist_img = fig_to_base64(fig)

# 5. Momentum Dynamics
df['SMA_50'] = df['Close'].rolling(window=50).mean()
df['SMA_200'] = df['Close'].rolling(window=200).mean()
df['Momentum_12M'] = df['Close'] / df['Close'].shift(252) - 1

fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(12, 8), height_ratios=[2, 1], sharex=True)
ax1.plot(df['Date'], df['Close'], color='#bdc3c7', alpha=0.7, label='Close')
ax1.plot(df['Date'], df['SMA_50'], color='#e67e22', linewidth=1.5, label='50-Day SMA')
ax1.plot(df['Date'], df['SMA_200'], color='#c0392b', linewidth=1.5, label='200-Day SMA')
ax1.set_title('Price & Moving Averages', fontsize=14, fontweight='bold')
ax1.legend()

ax2.bar(df['Date'], df['Momentum_12M'] * 100, color=np.where(df['Momentum_12M'] > 0, 'g', 'r'), alpha=0.5, width=2)
ax2.set_title('12-Month Momentum (%)', fontsize=12)
ax2.set_ylabel('Momentum (%)')
plt.tight_layout()
mom_img = fig_to_base64(fig)

